import {rateCases,meanCorrect,collisionCases,collisionCorrect} from './rate-models.js?v=20261023-physicscomplete01';
import {showRates} from './rate-scenes.js?v=20261023-physicscomplete01';
export function mountRateWidget(l,p,root,{save,done,feedback}){const mean=l.widget==='rates-mean',tasks=mean?rateCases:collisionCases,w=p.widget;w.task??=0;w.answers??={};w.passed??=[];const i=w.task%tasks.length,t=tasks[i],a=w.answers[t.id]??={};w.answers[t.id]=a;const $=s=>root.querySelector(s),valid=()=>mean?meanCorrect(t,a):collisionCorrect(t,a);let body=`<p><b>${i+1} / ${tasks.length} · ${t.title}</b></p>`,keys=[];
const select=(id,label,opts)=>`<label class="field-label" for="rate-${id}">${label}</label><select class="lab-select" id="rate-${id}"><option value="">Choose…</option>${opts.map(([v,s])=>`<option value="${v}">${s}</option>`).join('')}</select>`;
if(mean){body+=`<p>${t.quantity}: ${t.start} at ${t.t0} s; ${t.end} at ${t.t1} s. Calculate ${t.used?'reactant used':'product formed'} over this interval.</p>`;keys=['change','elapsed','rate'];body+=keys.map((k,j)=>`<label class="field-label" for="rate-${k}">${['Quantity change','Elapsed time / s','Mean rate / '+t.unit][j]}</label><input class="lab-input" id="rate-${k}" type="number" step="any">`).join('');}else{body+='<p>'+t.prompt+'</p>'+select('rate','Predicted reaction rate',[['slower','Slower'],['same','Unchanged'],['faster','Faster']])+select('reason','Why?',[['frequency','More frequent collisions'],['energy','More frequent and energetic collisions'],['surface','More collisions at exposed surface'],['barrier','Lower activation energy']]);keys=['rate','reason'];}
root.innerHTML=body+'<button class="secondary" id="checkRate">Check prediction</button><button class="secondary" id="nextRate">Next case →</button><p id="rateProgress">'+w.passed.length+' / '+tasks.length+' correct</p>';
const draw=()=>showRates(mean?'mean':'collision',t,w.passed.includes(t.id)&&valid());for(const k of keys){const el=$('#rate-'+k);el.value=a[k]??'';el[el.tagName==='INPUT'?'oninput':'onchange']=e=>{a[k]=e.target.value;save();draw();};}draw();$('#checkRate').onclick=()=>{if(!valid()){feedback(mean?'Subtract the two quantity readings for the amount formed or used, and subtract the times. Divide quantity change by that elapsed time.':'Match the mechanism to the changed condition. Concentration and gas pressure affect frequency; heating also raises collision energy; fragmentation exposes surface. These changes do not lower activation energy.',true);return;}if(!w.passed.includes(t.id))w.passed.push(t.id);save();draw();$('#rateProgress').textContent=w.passed.length+' / '+tasks.length+' correct';feedback(mean?'Correct: the quantity change and time interval give this mean rate.':'Correct: the rate prediction and collision explanation agree.');if(w.passed.length===tasks.length){p.widgetDone=true;save();done();}};$('#nextRate').onclick=()=>{w.task=(i+1)%tasks.length;save();feedback('');mountRateWidget(l,p,root,{save,done,feedback});};}
